38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's salutation: the {@code title} and {@code lastName} separated by a single
42	     * space (e.g. {@code "DR Franklin"}), or just the {@code lastName} when no title was supplied.
43	     */
44	    default String salutation(Owner owner) {
45	        String title = owner.getTitle();
46	        if (title == null || title.isBlank()) {
47	            return owner.getLastName();
48	        }
49	        return title + " " + owner.getLastName();
50	    }
51	
52	    /**
53	     * Derives the owner's age band from {@code birthDate}, computed against the
54	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18-64,
55	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date was supplied
56	     * (or the registration date is absent, e.g. seed data), so the field is simply absent.
57	     */
58	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
59	        java.time.LocalDate birthDate = owner.getBirthDate();
60	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
61	        if (birthDate == null || registrationDate == null) {
62	            return null;
63	        }
64	        int years = java.time.Period.between(birthDate, registrationDate).getYears();
65	        if (years < 18) {
66	            return OwnerDto.AgeBandEnum.MINOR;
67	        }
68	        if (years < 65) {
69	            return OwnerDto.AgeBandEnum.ADULT;
70	        }
71	        return OwnerDto.AgeBandEnum.SENIOR;
72	    }
73	
74	    /**
75	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
76	     * present, otherwise {@code PHONE}.
77	     */
78	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
79	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
80	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
81	    }
82	
83	    /**
84	     * The fixed city-to-region table: any city not listed derives locality {@code UNKNOWN}.
85	     */
86	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
87	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
88	
89	    /**
90	     * The fixed region-to-timezone table: maps a region code to its IANA timezone name. Any region
91	     * not listed (e.g. {@code UNKNOWN}) has no timezone.
92	     */
93	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
94	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
95	
96	    /**
97	     * Derives the owner's IANA timezone from the {@link #locality(Owner) locality/region} via the
98	     * fixed {@link #REGION_TIMEZONE} table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
99	     * QLD-&gt;Australia/Brisbane). Returns {@code null} when the region is not one of these, so the
100	     * field is simply absent.
101	     */
102	    default String timezone(Owner owner) {
103	        return REGION_TIMEZONE.get(locality(owner));
104	    }
105	
106	    /**
107	     * Derives the owner's locality from the region-and-hash identity: the REGION prefix of the
108	     * {@code customerCode} (everything before the first {@code '-'}). This is the same region the
109	     * identity is built from ({@link org.springframework.samples.petclinic.rest.function.owner.OwnerRegion},
110	     * postcode range first — NSW 2000-2099, VIC 3000-3099, QLD 4000-4099 — then the city table, then
111	     * {@code UNKNOWN}), so the locality a client reads back always matches the code's region prefix.
112	     * Owners with no {@code customerCode} (e.g. seed data) fall back to deriving the region directly.
113	     */
114	    default String locality(Owner owner) {
115	        String code = owner.getCustomerCode();
116	        if (code != null) {
117	            int dash = code.indexOf('-');
118	            if (dash > 0) {
119	                return code.substring(0, dash);
120	            }
121	        }
122	        return org.springframework.samples.petclinic.rest.function.owner.OwnerRegion.of(owner);
123	    }
124	
125	    /**
126	     * Derives the owner's membership points. Starts at 0; adds 2 when an email address is present;
127	     * adds 1 when the owner has no namesakes ({@code namesakeCount} is 0); adds 2 for a household of
128	     * 3 or more members ({@code householdMemberCount} is 3 or greater); adds 3 when the owner's
129	     * tenure exceeds 365 days. A newly created owner has zero tenure, so a new owner never earns the
130	     * tenure points.
131	     */
132	    default int membershipPoints(Owner owner) {
133	        int points = 0;
134	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
135	        if (hasEmail) {
136	            points += 2;
137	        }
138	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
139	        if (noNamesakes) {
140	            points += 1;
141	        }
142	        boolean largeHousehold = owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3;
143	        if (largeHousehold) {
144	            points += 2;
145	        }
146	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
147	        if (registrationDate != null
148	                && java.time.temporal.ChronoUnit.DAYS.between(registrationDate, java.time.LocalDate.now()) > 365) {
149	            points += 3;
150	        }
151	        return points;
152	    }
153	
154	    /**
155	     * Maps the owner's {@link #membershipPoints(Owner) membershipPoints} to a numeric level: 1 for
156	     * 0-1 points, 2 for 2-3 points, 3 for 4-5 points, 4 for 6 or more points.
157	     */
158	    default int membershipLevel(Owner owner) {
159	        int points = membershipPoints(owner);
160	        if (points <= 1) {
161	            return 1;
162	        }
163	        if (points <= 3) {
164	            return 2;
165	        }
166	        if (points <= 5) {
167	            return 3;
168	        }
169	        return 4;
170	    }
171	
172	    /**
173	     * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>} where YY is the
174	     * last two digits of the registrationDate year (e.g. {@code LON-SMI-0007-M26}). Returns {@code null}
175	     * when either source field is absent, so owners without a customer code or registration date
176	     * (e.g. seed data) simply have no membership number.
177	     */
178	    default String membershipNumber(Owner owner) {
179	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
180	            return null;
181	        }
182	        int yy = Math.floorMod(owner.getRegistrationDate().getYear(), 100);
183	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
184	    }
185	
186	    /**
187	     * Computes the owner's Luhn check digit (0-9) over the digits contained in the customerCode.
188	     * Returns {@code null} when the customer code is absent (e.g. seed data).
189	     */
190	    default Integer checkDigit(Owner owner) {
191	        String code = owner.getCustomerCode();
192	        if (code == null) {
193	            return null;
194	        }
195	        int sum = 0;
196	        boolean dbl = true;
197	        for (int i = code.length() - 1; i >= 0; i--) {
198	            char c = code.charAt(i);
199	            if (c < '0' || c > '9') {
200	                continue;
201	            }
202	            int d = c - '0';
203	            if (dbl) {
204	                d *= 2;
205	                if (d > 9) {
206	                    d -= 9;
207	                }
208	            }
209	            sum += d;
210	            dbl = !dbl;
211	        }
212	        return (10 - (sum % 10)) % 10;
213	    }
214	
