226	        OwnerPageDto ownerPageDto = new OwnerPageDto();
227	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
228	        ownerPageDto.setPage(ownerPage.getNumber());
229	        ownerPageDto.setSize(ownerPage.getSize());
230	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
231	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
232	        return ownerPageDto;
